"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["66110"],{72772(e){e.exports=JSON.parse('{"id":"FIN-064","slug":"debt-balance","term":"Debt Balance","also_known_as":[],"difficulty":"Beginner","definition":"A debt balance is the total amount still owed on a debt at a particular moment, including any unpaid interest and fees that have been added.","explanation":["When you take out a loan, the debt balance starts at the amount borrowed. Each payment reduces it, but interest and any fees increase it. The balance at any moment is what you would need to pay to clear the debt in full.","For example, if you borrow 12,000 and have repaid 3,500 of principal so far, your debt balance is 8,500. If a payment is missed and a late fee and extra interest are added, the balance rises.","On a credit card, the balance changes constantly with each purchase, payment, interest charge and fee. The statement balance shows what was owed on the statement date, while the current balance includes activity since then.","Watching debt balances matters for two reasons. Interest is usually charged on the balance, so a higher balance costs more each month. And lenders look at total balances when judging creditworthiness. A falling total balance over time is one of the clearest signs that debt is under control."],"note":"","total":1500,"prev":{"slug":"debt-avalanche","term":"Debt Avalanche"},"next":{"slug":"debt-collector","term":"Debt Collector"}}')}}]);